using System;
using System.Collections.Generic;
using Betta.Attributes;
using Rhino.Geometry;

namespace BenchPlugin.Facade
{
    /// <summary>
    /// One four-sided facade panel cut from a surface. Opaque, so it travels on its own wire
    /// between components. Geometry is computed once in the constructor.
    /// </summary>
    [GrasshopperOpaque]
    public sealed class Panel
    {
        private readonly Point3d[] _corners;
        private readonly double[] _edges;
        private readonly double[] _diagonals;

        public Panel(int index, IReadOnlyList<Point3d> corners)
        {
            if (corners == null || corners.Count != 4)
                throw new ArgumentException("A panel needs exactly four corners.", nameof(corners));

            Index = index;
            _corners = new[] { corners[0], corners[1], corners[2], corners[3] };

            Outline = new PolylineCurve(new[] { _corners[0], _corners[1], _corners[2], _corners[3], _corners[0] });

            _edges = new double[4];
            for (int k = 0; k < 4; k++)
                _edges[k] = _corners[k].DistanceTo(_corners[(k + 1) % 4]);

            _diagonals = new[]
            {
                _corners[0].DistanceTo(_corners[2]),
                _corners[1].DistanceTo(_corners[3]),
            };

            // Area: sum of the two triangles split along the first diagonal (exact for planar panels).
            Vector3d a = _corners[1] - _corners[0];
            Vector3d b = _corners[2] - _corners[0];
            Vector3d c = _corners[3] - _corners[0];
            Area = 0.5 * Vector3d.CrossProduct(a, b).Length + 0.5 * Vector3d.CrossProduct(b, c).Length;

            Center = new Point3d(
                (_corners[0].X + _corners[1].X + _corners[2].X + _corners[3].X) / 4.0,
                (_corners[0].Y + _corners[1].Y + _corners[2].Y + _corners[3].Y) / 4.0,
                (_corners[0].Z + _corners[1].Z + _corners[2].Z + _corners[3].Z) / 4.0);

            // Distance from the fourth corner to the plane through the first three.
            // Collinear first three corners define no plane: treated as infinitely non-planar.
            Vector3d normal = Vector3d.CrossProduct(b, a);
            if (normal.Length < 1e-12)
            {
                Deviation = double.PositiveInfinity;
            }
            else
            {
                normal.Unitize();
                Deviation = Math.Abs(Vector3d.Multiply(normal, c));
            }
        }

        /// <summary>Position in the grid (row-major: V row * U count + U column).</summary>
        public int Index { get; }

        /// <summary>Corners in order around the panel.</summary>
        public IReadOnlyList<Point3d> Corners => _corners;

        /// <summary>Closed outline through the four corners.</summary>
        public Curve Outline { get; }

        public double Area { get; }

        public Point3d Center { get; }

        /// <summary>Distance from the fourth corner to the plane through the other three.</summary>
        public double Deviation { get; }

        /// <summary>Nesting width: mean of the first and third edge lengths.</summary>
        public double Width => (_edges[0] + _edges[2]) / 2.0;

        /// <summary>Nesting height: mean of the second and fourth edge lengths.</summary>
        public double Height => (_edges[1] + _edges[3]) / 2.0;

        /// <summary>
        /// Six-value size fingerprint: the four edge lengths sorted, then the two diagonals sorted.
        /// </summary>
        public double[] SizeSignature()
        {
            var sig = new double[6];
            Array.Copy(_edges, sig, 4);
            Array.Sort(sig, 0, 4);
            sig[4] = Math.Min(_diagonals[0], _diagonals[1]);
            sig[5] = Math.Max(_diagonals[0], _diagonals[1]);
            return sig;
        }
    }
}

