using System;
using System.Collections.Generic;
using Rhino.Geometry;

namespace BenchPlugin.Facade.Services
{
    /// <summary>Divides a surface's domain evenly into a grid of panels.</summary>
    internal static class Panelizer
    {
        public static List<Panel> Panelize(Surface surface, int uCount, int vCount)
        {
            if (surface == null) throw new ArgumentException("Surface is required.");
            if (uCount < 1) throw new ArgumentOutOfRangeException(nameof(uCount), "U Count must be at least 1.");
            if (vCount < 1) throw new ArgumentOutOfRangeException(nameof(vCount), "V Count must be at least 1.");

            Interval du = surface.Domain(0);
            Interval dv = surface.Domain(1);

            // Grid of surface points: one per cell corner.
            var grid = new Point3d[uCount + 1, vCount + 1];
            for (int i = 0; i <= uCount; i++)
            {
                double u = du.T0 + du.Length * i / uCount;
                for (int j = 0; j <= vCount; j++)
                {
                    double v = dv.T0 + dv.Length * j / vCount;
                    grid[i, j] = surface.PointAt(u, v);
                }
            }

            var panels = new List<Panel>(uCount * vCount);
            for (int j = 0; j < vCount; j++)
            {
                for (int i = 0; i < uCount; i++)
                {
                    // Corners in order around the cell: (u0,v0), (u1,v0), (u1,v1), (u0,v1).
                    var corners = new[]
                    {
                        grid[i, j],
                        grid[i + 1, j],
                        grid[i + 1, j + 1],
                        grid[i, j + 1],
                    };
                    panels.Add(new Panel(j * uCount + i, corners));
                }
            }

            return panels;
        }
    }
}

