using System;
using System.Collections.Generic;
using System.Linq;

namespace BenchPlugin.Facade.Services
{
    /// <summary>Planarity classification and area statistics.</summary>
    internal static class PanelAnalysis
    {
        public const string FlatType = "flat";
        public const string ColdBentType = "cold-bent";
        public const string CustomType = "custom";

        public static string ClassifyDeviation(double deviation, double tolerance)
        {
            if (deviation <= tolerance) return FlatType;
            if (deviation <= 10.0 * tolerance) return ColdBentType;
            return CustomType;
        }

        public static (double Total, double Min, double Max, double Mean) AreaStats(IReadOnlyList<Panel> panels)
        {
            if (panels == null || panels.Count == 0)
                throw new InvalidOperationException("No panels to compute statistics for.");

            double total = 0, min = double.MaxValue, max = double.MinValue;
            foreach (var p in panels)
            {
                total += p.Area;
                min = Math.Min(min, p.Area);
                max = Math.Max(max, p.Area);
            }
            return (total, min, max, total / panels.Count);
        }
    }
}

