using System;
using System.Collections.Generic;

namespace BenchPlugin.Facade.Services
{
    /// <summary>Groups panels whose size fingerprints match within a tolerance.</summary>
    internal static class PanelGrouper
    {
        /// <summary>
        /// Each panel joins the first existing group whose representative it matches; otherwise it starts a
        /// new group and becomes its representative. Groups are numbered from 0 in order of first appearance.
        /// </summary>
        public static (List<int> Groups, List<Panel> Representatives) Group(IReadOnlyList<Panel> panels, double tolerance)
        {
            var groups = new List<int>(panels.Count);
            var representatives = new List<Panel>();
            var representativeSignatures = new List<double[]>();

            foreach (var panel in panels)
            {
                double[] sig = panel.SizeSignature();
                int group = -1;
                for (int g = 0; g < representativeSignatures.Count && group < 0; g++)
                {
                    if (Matches(sig, representativeSignatures[g], tolerance)) group = g;
                }

                if (group < 0)
                {
                    group = representatives.Count;
                    representatives.Add(panel);
                    representativeSignatures.Add(sig);
                }
                groups.Add(group);
            }

            return (groups, representatives);
        }

        private static bool Matches(double[] a, double[] b, double tolerance)
        {
            for (int k = 0; k < a.Length; k++)
            {
                if (Math.Abs(a[k] - b[k]) > tolerance) return false;
            }
            return true;
        }
    }
}

