using System;
using System.Collections.Generic;
using System.Linq;
using System.Threading;
using Rhino.Geometry;

namespace BenchPlugin.Facade.Services
{
    /// <summary>
    /// Shelf-packs panel rectangles onto sheets. Parts are taken tallest first and placed left to right on the
    /// current shelf; a part that doesn't fit starts a new shelf above, then a new sheet. A part is turned 90
    /// degrees only when it fits turned and not as it is. Parts are kept <c>spacing</c> apart and from the edges.
    /// </summary>
    internal static class ShelfNester
    {
        /// <summary>Gap between sheets along X, in model units, beyond the sheet width.</summary>
        public const double SheetGap = 100.0;

        private const double Epsilon = 1e-9;

        public sealed class Placement
        {
            public int PanelPosition { get; set; }   // position in the input panel list
            public int Sheet { get; set; }
            public double X { get; set; }            // lower-left corner within its sheet
            public double Y { get; set; }
            public double Width { get; set; }
            public double Height { get; set; }
        }

        public sealed class Result
        {
            public List<Placement> Placed { get; } = new List<Placement>();
            public List<int> Unplaced { get; } = new List<int>();
            public int SheetCount { get; set; }
            public double Utilization { get; set; }
        }

