            public double Height { get; }
            public double Spacing { get; }
        }

        private static bool TryPlace(
            List<SheetState> sheets, Context ctx, Result result, int panelPos, double w, double h)
        {
            if (sheets.Count > 0)
            {
                int sheetIndex = sheets.Count - 1;
                SheetState state = sheets[sheetIndex];

                // 1-2: the current shelf, as is, then turned.
                if (TryOnShelf(state.Current, sheetIndex, panelPos, w, h, ctx, result)) return true;

                // 3-4: a new shelf above, if the current shelf holds anything.
                if (state.Current.Height > 0)
                {
                    var shelf = new Shelf
                    {
                        Bottom = state.Current.Bottom + state.Current.Height + ctx.Spacing,
                        Height = 0,
                        Cursor = ctx.Spacing,
                    };
                    if (TryOnShelf(shelf, sheetIndex, panelPos, w, h, ctx, result))
                    {
                        state.Current = shelf;
                        return true;
                    }
                }
            }

            // 5-6: a new sheet, only if the part fits an empty sheet in one of its orientations.
            var fresh = new Shelf { Bottom = ctx.Spacing, Height = 0, Cursor = ctx.Spacing };
            int newSheetIndex = sheets.Count;
            if (TryOnShelf(fresh, newSheetIndex, panelPos, w, h, ctx, result))
            {
                sheets.Add(new SheetState { Current = fresh });
                return true;
            }
            return false;
        }

        /// <summary>
        /// Tries the part as is, then turned, on one shelf. Records the placement and advances the shelf only
        /// when it succeeds.
        /// </summary>
        private static bool TryOnShelf(
            Shelf shelf, int sheetIndex, int panelPos, double w, double h, Context ctx, Result result)
        {
            if (Fits(shelf, w, h, ctx))
            {
                Place(shelf, sheetIndex, panelPos, w, h, ctx, result);
                return true;
            }
            if (Fits(shelf, h, w, ctx))
            {
                Place(shelf, sheetIndex, panelPos, h, w, ctx, result);
                return true;
            }
            return false;
        }

        private static bool Fits(Shelf shelf, double w, double h, Context ctx)
        {
            bool fitsX = shelf.Cursor + w <= ctx.Width - ctx.Spacing + Epsilon;
            bool fitsY = shelf.Bottom + Math.Max(shelf.Height, h) <= ctx.Height - ctx.Spacing + Epsilon;
            return fitsX && fitsY;
        }

        private static void Place(
            Shelf shelf, int sheetIndex, int panelPos, double w, double h, Context ctx, Result result)
        {
            result.Placed.Add(new Placement
            {
                PanelPosition = panelPos,
                Sheet = sheetIndex,
                X = shelf.Cursor,
                Y = shelf.Bottom,
                Width = w,
                Height = h,
