using System;
using System.Collections.Generic;
using System.Linq;
using System.Threading;

namespace BenchPlugin.Facade.Services
{
    /// <summary>
    /// Shelf-packs panel rectangles onto sheets. Parts are taken tallest first and placed left to right on the
    /// current shelf. A part that doesn't fit starts a new shelf above, a shelf that doesn't fit starts a new
    /// sheet. A part is turned 90 degrees only when it fits turned and not as it is. Parts are kept
    /// <c>spacing</c> apart and from the sheet edges.
    /// </summary>
    internal static class ShelfNester
    {
        /// <summary>Extra gap between sheets along X, beyond the sheet width.</summary>
        public const double SheetGap = 100.0;

        private const double Epsilon = 1e-9;

        public sealed class Placement
        {
            public int PanelPosition { get; set; }   // position in the input panel list
            public int Sheet { get; set; }
            public double X { get; set; }            // lower-left corner within its sheet
            public double Y { get; set; }
            public double Width { get; set; }
            public double Height { get; set; }
        }

        public sealed class Result
        {
            public List<Placement> Placed { get; } = new List<Placement>();
            public List<int> Unplaced { get; } = new List<int>();
            public int SheetCount { get; set; }
            public double Utilization { get; set; }
        }

        private sealed class Shelf
        {
            public double Bottom;      // y of the shelf
            public double Height;      // tallest part placed on the shelf so far
            public double Cursor;      // next free x on the shelf
        }

        private sealed class SheetState
        {
            public Shelf Current;
        }

        public static Result Nest(
            IReadOnlyList<Panel> panels,
            double sheetWidth,
            double sheetHeight,
            double spacing,
            IProgress<int> progress,
            CancellationToken cancellationToken)
        {
            if (sheetWidth <= 0) throw new ArgumentOutOfRangeException(nameof(sheetWidth), "Sheet Width must be positive.");
            if (sheetHeight <= 0) throw new ArgumentOutOfRangeException(nameof(sheetHeight), "Sheet Height must be positive.");
            if (spacing < 0) throw new ArgumentOutOfRangeException(nameof(spacing), "Spacing can't be negative.");

            var result = new Result();
            var sheets = new List<SheetState>();
            int count = panels.Count;

            // Tallest first; ties broken by width.
            var order = Enumerable.Range(0, count)
                .OrderByDescending(i => panels[i].Height)
                .ThenByDescending(i => panels[i].Width)
                .ToList();

            var sheet = new Context(sheetWidth, sheetHeight, spacing);
            int lastPercent = -1;
            for (int k = 0; k < order.Count; k++)
            {
                cancellationToken.ThrowIfCancellationRequested();

                int panelPos = order[k];
                Panel panel = panels[panelPos];

                if (!TryPlace(sheets, sheet, result, panelPos, panel.Width, panel.Height))
                    result.Unplaced.Add(panelPos);

                int percent = (k + 1) * 100 / count;
                if (percent != lastPercent)
                {
                    lastPercent = percent;
                    progress?.Report(percent);
                }
            }

            result.SheetCount = sheets.Count;
            double usedArea = result.Placed.Sum(p => p.Width * p.Height);
            double totalSheetArea = sheets.Count * sheetWidth * sheetHeight;
            result.Utilization = totalSheetArea > 0 ? usedArea / totalSheetArea : 0.0;
            return result;
        }

        private sealed class Context
        {
            public Context(double width, double height, double spacing)
            {
                Width = width;
                Height = height;
                Spacing = spacing;
            }

            public double Width { get; }
            public double Height { get; }
            public double Spacing { get; }
        }

        private static bool TryPlace(
            List<SheetState> sheets, Context ctx, Result result, int panelPos, double w, double h)
        {
            if (sheets.Count > 0)
            {
                int sheetIndex = sheets.Count - 1;
                SheetState state = sheets[sheetIndex];

                // 1-2: the current shelf, as is, then turned.
                if (TryOnShelf(state.Current, sheetIndex, panelPos, w, h, ctx, result)) return true;

                // 3-4: a new shelf above, if the current shelf holds anything.
                if (state.Current.Height > 0)
                {
                    var shelf = new Shelf
                    {
                        Bottom = state.Current.Bottom + state.Current.Height + ctx.Spacing,
                        Height = 0,
                        Cursor = ctx.Spacing,
                    };
                    if (TryOnShelf(shelf, sheetIndex, panelPos, w, h, ctx, result))
                    {
                        state.Current = shelf;
                        return true;
                    }
                }
            }

            // 5-6: a new sheet, only if the part fits an empty sheet in one of its orientations.
            var fresh = new Shelf { Bottom = ctx.Spacing, Height = 0, Cursor = ctx.Spacing };
            int newSheetIndex = sheets.Count;
            if (TryOnShelf(fresh, newSheetIndex, panelPos, w, h, ctx, result))
            {
                sheets.Add(new SheetState { Current = fresh });
                return true;
            }
            return false;
        }

        /// <summary>
        /// Tries the part as is, then turned, on one shelf. Records the placement and advances the shelf only
        /// when it succeeds.
        /// </summary>
        private static bool TryOnShelf(
            Shelf shelf, int sheetIndex, int panelPos, double w, double h, Context ctx, Result result)
        {
            if (Fits(shelf, w, h, ctx))
            {
                Place(shelf, sheetIndex, panelPos, w, h, ctx, result);
                return true;
            }
            if (Fits(shelf, h, w, ctx))
            {
                Place(shelf, sheetIndex, panelPos, h, w, ctx, result);
                return true;
            }
            return false;
        }

        private static bool Fits(Shelf shelf, double w, double h, Context ctx)
        {
            bool fitsX = shelf.Cursor + w <= ctx.Width - ctx.Spacing + Epsilon;
            bool fitsY = shelf.Bottom + Math.Max(shelf.Height, h) <= ctx.Height - ctx.Spacing + Epsilon;
            return fitsX && fitsY;
        }

        private static void Place(
            Shelf shelf, int sheetIndex, int panelPos, double w, double h, Context ctx, Result result)
        {
            result.Placed.Add(new Placement
            {
                PanelPosition = panelPos,
                Sheet = sheetIndex,
                X = shelf.Cursor,
                Y = shelf.Bottom,
                Width = w,
                Height = h,
            });
            shelf.Cursor += w + ctx.Spacing;
            shelf.Height = Math.Max(shelf.Height, h);
        }
    }
}

