using System;
using System.Collections.Generic;
using System.Linq;
using System.Threading;
using Rhino.Geometry;

namespace BenchPlugin.Facade.Services
{
    /// <summary>
    /// Shelf-packs panel rectangles onto sheets. Parts are taken tallest first and placed left to right on the
    /// current shelf; a part that doesn't fit starts a new shelf above, then a new sheet. A part is turned 90
    /// degrees only when it fits turned and not as it is. Parts are kept <c>spacing</c> apart and from the edges.
    /// </summary>
    internal static class ShelfNester
    {
        /// <summary>Gap between sheets along X, in model units, beyond the sheet width.</summary>
        public const double SheetGap = 100.0;

        private const double Epsilon = 1e-9;

        public sealed class Placement
        {
            public int PanelPosition { get; set; }   // position in the input panel list
            public int Sheet { get; set; }
            public double X { get; set; }            // lower-left corner within its sheet
            public double Y { get; set; }
            public double Width { get; set; }
            public double Height { get; set; }
        }

        public sealed class Result
        {
            public List<Placement> Placed { get; } = new List<Placement>();
            public List<int> Unplaced { get; } = new List<int>();
            public int SheetCount { get; set; }
            public double Utilization { get; set; }
        }

        private sealed class Sheet
        {
            public double ShelfBottom;   // y of the current shelf
            public double ShelfHeight;   // tallest part placed on the current shelf so far
            public double Cursor;        // next free x on the current shelf
        }

        public static Result Nest(
            IReadOnlyList<Panel> panels,
            double sheetWidth,
            double sheetHeight,
            double spacing,
            IProgress<int> progress,
            CancellationToken cancellationToken)
        {
            if (sheetWidth <= 0) throw new ArgumentOutOfRangeException(nameof(sheetWidth), "Sheet Width must be positive.");
            if (sheetHeight <= 0) throw new ArgumentOutOfRangeException(nameof(sheetHeight), "Sheet Height must be positive.");
            if (spacing < 0) throw new ArgumentOutOfRangeException(nameof(spacing), "Spacing can't be negative.");

            var result = new Result();
            var sheets = new List<Sheet>();
            int count = panels.Count;

            // Tallest first; ties broken by width.
            var order = Enumerable.Range(0, count)
                .OrderByDescending(i => panels[i].Height)
                .ThenByDescending(i => panels[i].Width)
                .ToList();

            int lastPercent = -1;
            for (int k = 0; k < order.Count; k++)
            {
                cancellationToken.ThrowIfCancellationRequested();

                int panelPos = order[k];
                Panel panel = panels[panelPos];
                double w = panel.Width;
                double h = panel.Height;

                if (!TryPlace(sheets, result, panelPos, w, h, sheetWidth, sheetHeight, spacing))
                    result.Unplaced.Add(panelPos);

                int percent = (k + 1) * 100 / count;
                if (percent != lastPercent)
                {
                    lastPercent = percent;
                    progress?.Report(percent);
                }
            }

            result.SheetCount = sheets.Count;
            double usedArea = result.Placed.Sum(p => p.Width * p.Height);
            double sheetArea = sheetWidth * sheetHeight;
            result.Utilization = sheets.Count == 0 ? 0.0 : usedArea / (sheets.Count * sheetArea);
            return result;
        }

        private static bool TryPlace(
            List<Sheet> sheets, Result result, int panelPos, double w, double h,
            double sheetWidth, double sheetHeight, double spacing)
        {
            // 1-2: the current sheet's current shelf, as is, then turned.
            if (sheets.Count > 0)
            {
                Sheet current = sheets[sheets.Count - 1];
                int sheetIndex = sheets.Count - 1;

                if (TryOnShelf(current, sheetIndex, panelPos, w, h, sheetWidth, sheetHeight, spacing, result)) return true;

                // 3-4: a new shelf above on the current sheet, if the current shelf has anything on it.
                if (current.ShelfHeight > 0)
                {
                    double newBottom = current.ShelfBottom + current.ShelfHeight + spacing;
                    var shelf = new Sheet { ShelfBottom = newBottom, ShelfHeight = 0, Cursor = spacing };
                    if (TryOnShelf(shelf, sheetIndex, panelPos, w, h, sheetWidth, sheetHeight, spacing, result))
                    {
                        sheets[sheetIndex] = shelf;
                        return true;
                    }
                }
            }

            // 5-6: a new sheet, only if the part fits an empty sheet in either orientation.
            var fresh = new Sheet { ShelfBottom = spacing, ShelfHeight = 0, Cursor = spacing };
            var freshSheetIndex = sheets.Count;
            if (TryOnShelf(fresh, freshSheetIndex, panelPos, w, h, sheetWidth, sheetHeight, spacing, result))
            {
                sheets.Add(fresh);
                return true;
            }
            return false;
        }

        /// <summary>
        /// Tries the part as is, then turned, on the given shelf. Records the placement and updates the shelf
        /// state on success. A shelf's own state is mutated only on success, so a failed try leaves it untouched.
        /// </summary>
        private static bool TryOnShelf(
            Sheet shelf, int sheetIndex, int panelPos, double w, double h,
            double sheetWidth, double sheetHeight, double spacing, Result result)
        {
            if (Fits(shelf, w, h, sheetWidth, sheetHeight, spacing)) return Place(shelf, sheetIndex, panelPos, w, h, result);
            if (Fits(shelf, h, w, sheetWidth, sheetHeight, spacing)) return Place(shelf, sheetIndex, panelPos, h, w, result);
            return false;
        }

        private static bool Fits(Sheet shelf, double w, double h, double sheetWidth, double sheetHeight, double spacing)
        {
            bool fitsX = shelf.Cursor + w <= sheetWidth - spacing + Epsilon;
            bool fitsY = shelf.ShelfBottom + Math.Max(shelf.ShelfHeight, h) <= sheetHeight - spacing + Epsilon;
            return fitsX && fitsY;
        }

        private static bool Place(Sheet shelf, int sheetIndex, int panelPos, double w, double h, Placement_Holder_Result result)
        {
            return false;
        }
    }
}

