using System;
using System.Collections.Generic;
using System.Globalization;
using System.IO;
using System.Text;

namespace BenchPlugin.Facade.Services
{
    /// <summary>Builds the cut list CSV. Width and height match the nesting dimensions.</summary>
    internal static class CutListBuilder
    {
        public const string Header = "Index,Width,Height,Area,Deviation";

        public static string BuildCsv(IEnumerable<Panel> panels)
        {
            var sb = new StringBuilder();
            sb.Append(Header).Append("\r\n");
            foreach (var p in panels)
            {
                sb.Append(p.Index.ToString(CultureInfo.InvariantCulture)).Append(',')
                  .Append(Format(p.Width)).Append(',')
                  .Append(Format(p.Height)).Append(',')
                  .Append(Format(p.Area)).Append(',')
                  .Append(Format(p.Deviation)).Append("\r\n");
            }
            return sb.ToString();
        }

        public static void Write(string path, string csv)
        {
            if (string.IsNullOrWhiteSpace(path))
                throw new ArgumentException("Path is empty; set a file path to write the cut list.");
            File.WriteAllText(path, csv, Encoding.UTF8);
        }

        private static string Format(double value) => value.ToString("0.###", CultureInfo.InvariantCulture);
    }
}

