namespace BenchPlugin.Facade.Components
{
    [GrasshopperCollection("Facade", "Panels")]
    public class PanelCollection : IBettaCollection
    {
        [GrasshopperMethod("Panelize Surface", "Divides a surface into a grid of four-sided panels")]
        public (List<Panel> Panels, List<Curve> Outlines) PanelizeSurface(
            [GrasshopperParameter("Surface")] Surface surface,
            [GrasshopperParameter("U Count", DefaultValue = 10)] int uCount,
            [GrasshopperParameter("V Count", DefaultValue = 6)] int vCount)
        {
            List<Panel> panels = Panelizer.Panelize(surface, uCount, vCount);
