using System;
using System.Collections.Generic;
using System.Threading;
using System.Threading.Tasks;
using Betta.Attributes;
using Betta.Interfaces;
using BenchPlugin.Facade.Services;
using Rhino.Geometry;

namespace BenchPlugin.Facade.Components
{
    [GrasshopperCollection("Facade", "Fabrication")]
    public class FabricationCollection : IBettaCollection
    {
        [GrasshopperMethod("Group Identical Panels", "Groups panels whose sorted edge and diagonal lengths match within tolerance")]
        public (List<int> Group, int GroupCount, List<Panel> Representatives) GroupIdenticalPanels(
            [GrasshopperParameter("Panels")] List<Panel> panels,
            [GrasshopperParameter("Tolerance", DefaultValue = 1.0)] double tolerance)
        {
            panels ??= new List<Panel>();
            var (groups, representatives) = PanelGrouper.Group(panels, tolerance);
            return (groups, representatives.Count, representatives);
        }

        [GrasshopperMethod("Nest On Sheets", "Shelf-packs panel rectangles onto sheets, running in the background")]
        public async Task<(List<Curve> Outlines, List<int> Sheet, int SheetCount, double Utilization)> NestOnSheets(
            [GrasshopperParameter("Panels")] List<Panel> panels,
            [GrasshopperParameter("Sheet Width", DefaultValue = 3000.0)] double sheetWidth,
            [GrasshopperParameter("Sheet Height", DefaultValue = 1500.0)] double sheetHeight,
            [GrasshopperParameter("Spacing", DefaultValue = 10.0)] double spacing,
            IProgress<int> progress,
            IBettaReport report,
            CancellationToken cancellationToken)
        {
            panels ??= new List<Panel>();
            var snapshot = new List<Panel>(panels);

            ShelfNester.Result nest = await Task.Run(
                () => ShelfNester.Nest(snapshot, sheetWidth, sheetHeight, spacing, progress, cancellationToken),
                cancellationToken).ConfigureAwait(false);

            if (nest.Unplaced.Count > 0)
            {
                report.Warning($"{nest.Unplaced.Count} of {snapshot.Count} panels fit on no sheet and were left out.");
            }

            var outlines = new List<Curve>(nest.Placed.Count);
            var sheet = new List<int>(nest.Placed.Count);
            foreach (var part in nest.Placed)
            {
                double ox = part.Sheet * (sheetWidth + ShelfNester.SheetGap);
                double x0 = ox + part.X, x1 = x0 + part.Width;
                double y0 = part.Y, y1 = y0 + part.Height;
                outlines.Add(new PolylineCurve(new[]
                {
                    new Point3d(x0, y0, 0), new Point3d(x1, y0, 0),
                    new Point3d(x1, y1, 0), new Point3d(x0, y1, 0),
                    new Point3d(x0, y0, 0),
                }));
                sheet.Add(part.Sheet);
            }

            return (outlines, sheet, nest.SheetCount, nest.Utilization);
        }

        [GrasshopperMethod("Cut List", "CSV of index, width, height, area and deviation per panel; optionally written to a file")]
        public (string CSV, bool Written) CutList(
            [GrasshopperParameter("Panels")] List<Panel> panels,
            [GrasshopperParameter("Path", DefaultValue = "")] string path,
            [GrasshopperParameter("Write", DefaultValue = false)] bool write)
        {
            panels ??= new List<Panel>();
            string csv = CutListBuilder.BuildCsv(panels);

            if (!write) return (csv, false);

            CutListBuilder.Write(path, csv);
            return (csv, true);
        }
    }
}

